// Writes manifest.ts into a registry folder: one default import per part
// file, sorted by file name, so two branches that each add a part conflict
// only in this generated file and the fix is to regenerate.
//
//   bun <your copy>/registry/manifest.ts <registry folder> [--check] [--doc <file.md>]
//
// `--check` fails when the committed file is stale; `--doc` also writes a
// markdown table of every part, for a design sheet to point at.
import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import type { Contract, PartDefinition } from "./types";

/** Files in a registry folder that are not parts. A project keeps its part
 * files alone in the folder, beside the generated manifest and this
 * script's wrapper if it has one. */
const NOT_PARTS = new Set(["types.ts", "define.ts", "manifest.ts", "part.ts"]);

/** Part files on disk, sorted by file name with a fixed locale. */
export function partFiles(folder: string): string[] {
  return readdirSync(folder)
    .filter(
      (f) => f.endsWith(".ts") && !NOT_PARTS.has(f) && !f.endsWith(".test.ts"),
    )
    .toSorted((a, b) => a.localeCompare(b, "en"));
}

/** `list-group-label.ts` becomes the identifier `listGroupLabel`. */
function identifier(file: string): string {
  const base = file.replace(/\.ts$/, "");
  return base.replaceAll(/-([a-z0-9])/g, (_m, c: string) => c.toUpperCase());
}

export function renderManifest(
  entries: readonly { file: string; name: string }[],
): string {
  const imports = entries.map(
    (e) =>
      `import ${identifier(e.file)} from "./${e.file.replace(/\.ts$/, "")}";`,
  );
  const names = entries.map((e) => `  ${JSON.stringify(e.name)},`);
  const all = entries.map((e) => `  ${identifier(e.file)},`);
  return [
    "// Generated by registry/manifest.ts; do not edit; regenerate instead",
    ...imports,
    'import type { PartDefinition } from "./types";',
    "",
    "const all: readonly PartDefinition[] = [",
    ...all,
    "];",
    "",
    "export const parts: Readonly<Record<string, PartDefinition>> =",
    "  Object.fromEntries(all.map((p) => [p.name, p]));",
    "",
    "export const partNames = [",
    ...names,
    "] as const;",
    "",
    "export type PartName = (typeof partNames)[number];",
    "",
  ].join("\n");
}

/** Table cells cannot hold a pipe or a line break. */
function cell(text: string): string {
  return text.replaceAll("|", String.raw`\|`).replaceAll("\n", " ");
}

function list(items: readonly string[]): string {
  return items.length === 0 ? "none" : items.map((i) => `\`${i}\``).join(", ");
}

/** A contract as plain "kind(args)" text: the kind and its arguments. */
export function renderContract(contract: Contract): string {
  const { kind, ...rest } = contract as { kind: string } & Record<
    string,
    unknown
  >;
  const args = Object.entries(rest).map(([k, v]) => {
    if (Array.isArray(v)) return `${k}=[${v.join(",")}]`;
    // A guard prints as `when=shape:stacked`.
    if (k === "when" && v && typeof v === "object") {
      const g = v as {
        attr: string;
        value: string | readonly string[];
        not?: true;
      };
      const value = typeof g.value === "string" ? g.value : g.value.join("/");
      return `when=${g.not ? "not " : ""}${g.attr}:${value}`;
    }
    return `${k}=${String(v)}`;
  });
  return `${kind}(${args.join(", ")})`;
}

/** The generated parts doc: one table, same order as the manifest, so the
 * design sheet can point here instead of keeping its own copy. */
export function renderDoc(defs: readonly PartDefinition[]): string {
  const head = [
    "Part",
    "Level",
    "Purpose",
    "Within",
    "Contains",
    "Contracts",
    "Style variants",
  ];
  const body = defs.map((d) => {
    const contracts =
      d.contracts.length === 0
        ? "none"
        : d.contracts.map((c) => `\`${renderContract(c)}\``).join("<br>");
    const variants = Object.keys(d.style ?? {});
    return [
      `\`${d.name}\``,
      String(d.level),
      cell(d.purpose),
      list(d.within),
      list(d.contains),
      contracts,
      list(variants),
    ];
  });
  // Padded to column width so oxfmt leaves the file as written; otherwise
  // --check and the formatter would fight over it.
  const widths = head.map((h, i) =>
    Math.max(h.length, ...body.map((r) => (r[i] as string).length)),
  );
  const line = (cells: readonly string[]): string =>
    `| ${cells.map((c, i) => c.padEnd(widths[i] as number)).join(" | ")} |`;
  const rows = [
    line(head),
    `| ${widths.map((w) => "-".repeat(w)).join(" | ")} |`,
    ...body.map(line),
  ];
  return [
    "<!-- Generated by bun run gen:parts from packages/taste/src/parts; never hand-edited. -->",
    "",
    "# Parts",
    "",
    "Generated from the parts registry; never hand-edited.",
    "",
    ...rows,
    "",
  ].join("\n");
}

export async function generateAll(
  folder: string,
): Promise<{ manifest: string; doc: string }> {
  const entries: { file: string; name: string }[] = [];
  const defs: PartDefinition[] = [];
  for (const file of partFiles(folder)) {
    const mod = (await import(pathToFileURL(path.join(folder, file)).href)) as {
      default: PartDefinition;
    };
    entries.push({ file, name: mod.default.name });
    defs.push(mod.default);
  }
  return { manifest: renderManifest(entries), doc: renderDoc(defs) };
}

export async function generate(folder: string): Promise<string> {
  return (await generateAll(folder)).manifest;
}

function read(f: string): string {
  return existsSync(f) ? readFileSync(f, "utf8") : "";
}

if (import.meta.main) {
  const args = process.argv.slice(2);
  const folderArg = args.find((a) => !a.startsWith("--"));
  if (folderArg === undefined) {
    console.error(
      "usage: bun registry/manifest.ts <registry folder> [--check] [--doc <file.md>]",
    );
    process.exit(2);
  }
  const folder = path.resolve(folderArg);
  const manifestFile = path.join(folder, "manifest.ts");
  const docIndex = args.indexOf("--doc");
  const docFile =
    docIndex === -1 ? undefined : path.resolve(args[docIndex + 1] ?? "");
  const next = await generateAll(folder);
  const targets: [string, string][] = [[manifestFile, next.manifest]];
  if (docFile !== undefined) targets.push([docFile, next.doc]);
  if (args.includes("--check")) {
    const stale = targets.filter(([f, text]) => read(f) !== text);
    for (const [f] of stale) {
      console.error(
        `${path.relative(process.cwd(), f)} is stale; regenerate it`,
      );
    }
    if (stale.length > 0) process.exit(1);
    console.log("parts manifest is up to date");
  } else {
    for (const [f, text] of targets) writeFileSync(f, text);
    console.log(
      `wrote ${targets.map(([f]) => path.relative(process.cwd(), f)).join(" and ")}`,
    );
  }
}
